'use strict';

/**
@param {{ isTTY?: boolean | undefined }} stream
@returns {number}
*/
function colorDepth(stream) {
  if (stream && !stream.isTTY) return 0;
  return 1;
}

/**
@param {{ isTTY?: boolean | undefined }} stream
@returns {boolean}
*/
function linkSupport(stream) {
  const { FORCE_LINKS } = process.env;
  if (FORCE_LINKS) return FORCE_LINKS !== '0';
  if (colorDepth(stream) === 0) return false;
  if (stream && !stream.isTTY) return false;
  return true;
}

module.exports = {
  linkSupport,
  stdout: linkSupport(process.stdout),
  stderr: linkSupport(process.stderr),
};
